class Solution {
    public int balancedStringSplit(String s) {
        int balance = 0, count = 0;
        for (char c : s.toCharArray()) {
            balance += c == 'R' ? 1 : -1;
            if (balance == 0) count++;
        }
        return count;
    }
}

class Solution {
    public int balancedStringSplit(String s) {
        int depth = 0, count = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'L') {
                depth++;
            } else {
                depth--;
            }
            if (depth == 0) count++;
        }
        return count;
    }
}
